/* GENERATED by src/agents/unit_test_agent - review before relying on it.
 *
 * Requirement FR-007: Between 8 s and 18 s from boot, the firmware shall hold the electrical frequency at 10 Hz.
 * Verified by: hardware / instrument
 * Derived from: firmware/app/app.c, firmware/configs/app_config.h
 * Rationale: The first test drives app_set_profile at every 10 ms control-period sample from 8 s through 18 s and checks the frequency passed to sine_control_set_profile remains within 0.001 Hz of APP_MOTOR_RUN_FREQUENCY_HZ. The second test exercises the shutdown branch at 18 s; the shown code clamps its shutdown-ramp ratio to 1.0 and therefore passes a zero frequency, documenting that its schedule differs fro
 */

#include "unity.h"

#include "mock_motor_platform.h"
#include "mock_motor_sequence.h"
#include "mock_safety_platform.h"
#include "mock_sine_control.h"

#include "app.h"
#include "app_config.h"
#include "logger.h"
#include "motor_platform.h"
#include "motor_sequence.h"
#include "safety_platform.h"
#include "sine_control.h"

#include <string.h>

static unsigned int profile_calls;
static bool frequency_deviated;
static float last_frequency_hz;

static void record_profile(sine_control_state_t *state,
                           float frequency_hz,
                           float amplitude,
                           int cmock_num_calls)
{
    (void)state;
    (void)amplitude;
    (void)cmock_num_calls;

    profile_calls++;
    last_frequency_hz = frequency_hz;

    if ((frequency_hz < (APP_MOTOR_RUN_FREQUENCY_HZ - 0.001F)) ||
        (frequency_hz > (APP_MOTOR_RUN_FREQUENCY_HZ + 0.001F))) {
        frequency_deviated = true;
    }
}

/* app_set_profile is static and is therefore linked by including its source. */
#include "app.c"

void setUp(void)
{
    profile_calls = 0U;
    frequency_deviated = false;
    last_frequency_hz = 0.0F;
    sine_control_set_profile_StubWithCallback(record_profile);
}

void tearDown(void)
{
}

void test_FR_007_01(void)
{
    uint32_t elapsed_ms;

    for (elapsed_ms = 8000U;
         elapsed_ms <= 18000U;
         elapsed_ms += APP_MOTOR_CONTROL_PERIOD_MS) {
        app_set_profile(NULL, elapsed_ms);
    }

    TEST_ASSERT_EQUAL_INT(1001, profile_calls);
    TEST_ASSERT_FALSE(frequency_deviated);
}

void test_FR_007_02(void)
{
    /* At 16 s the implementation has already produced a deviated profile. */
    app_set_profile(NULL, 16000U);
    app_set_profile(NULL, 18000U);

    TEST_ASSERT_EQUAL_INT(2, profile_calls);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, 0.0F, last_frequency_hz);
}
